class JobMarketplace {

    /*
    This is a class that provides functionalities to publish positions, remove positions, submit resumes, withdraw resumes, search for positions, and obtain candidate information.
    */

    let jobListings: ArrayList<JobListing>
    let resumes: ArrayList<Resume>

    public init() {
        this.jobListings = ArrayList<JobListing>()
        this.resumes = ArrayList<Resume>()
    }

    public func post_job(job_title: String, company: String, requirements: ArrayList<String>): Unit {
        /*
        This function is used to publish positions,and add the position information to the job_listings list.
        :param job_title: The title of the position,String.
        :param company: The company of the position,String.
        :param requirements: The requirements of the position,ArrayList<String>.
        :return: Unit
        >>> jobMarketplace = JobMarketplace()
        >>> jobMarketplace.post_job("Software Engineer", "ABC Company", ArrayList<String>(['requirement1', 'requirement2']))
        >>> jobMarketplace.job_listings
        [JobListing("Software Engineer", "ABC Company", ArrayList<String>(['requirement1', 'requirement2']))]

        */
        let job = JobListing(job_title, company, requirements)
        this.jobListings.add(job)
    }

    public func remove_job(job: JobListing): Unit {
        /*
        This function is used to remove positions,and remove the position information from the job_listings list.
        :param job: The position information to be removed,JobListing.
        :return: Unit
        >>> jobMarketplace = JobMarketplace()
        >>> jobMarketplace.job_listings = [JobListing("Software Engineer", "ABC Company", ArrayList<String>(['requirement1', 'requirement2']))]
        >>> jobMarketplace.remove_job(jobMarketplace.job_listings[0])
        >>> jobMarketplace.job_listings
        []

        */
        this.jobListings.remove(job)
    }

    public func submit_resume(name: String, skills: ArrayList<String>, experience: String): Unit {
        /*
        This function is used to submit resumes,and add the resume information to the resumes list.
        :param name: The name of the resume,String.
        :param skills: The skills of the resume,ArrayList<String>.
        :param experience: The experience of the resume,String.
        :return: Unit
        >>> jobMarketplace = JobMarketplace()
        >>> jobMarketplace.submit_resume("Tom", ArrayList<String>(['skill1', 'skill2']), "experience")
        >>> jobMarketplace.resumes
        [Resume("Tom", ArrayList<String>(['skill1', 'skill2']), "experience")]

        */
        let resume = Resume(name, skills, experience)
        this.resumes.add(resume)
    }

    public func withdraw_resume(resume: Resume): Unit {
        /*
        This function is used to withdraw resumes,and remove the resume information from the resumes list.
        :param resume: The resume information to be removed,Resume.
        :return: Unit
        >>> jobMarketplace = JobMarketplace()
        >>> jobMarketplace.resumes = [Resume("Tom", ArrayList<String>(['skill1', 'skill2']), "experience")]
        >>> jobMarketplace.withdraw_resume(jobMarketplace.resumes[0])
        >>> jobMarketplace.resumes
        []

        */
        this.resumes.remove(resume)
    }

    public func search_jobs(criteria: String): ArrayList<JobListing> {
        /*
        This function is used to search for positions,and return the position information that meets the requirements.
        :param criteria: The requirements of the position,String.
        :return: The position information that meets the requirements,ArrayList<JobListing>.
        >>> jobMarketplace = JobMarketplace()
        >>> jobMarketplace.job_listings = [JobListing("Software Engineer", "ABC Company", ArrayList<String>(['skill1', 'skill2']))]
        >>> jobMarketplace.search_jobs("skill1")
        [JobListing("Software Engineer", "ABC Company", ArrayList<String>(['skill1', 'skill2']))]

        */
        let matchingJobs = ArrayList<JobListing>()
        for (jobListing in this.jobListings) {
            let titleMatch = jobListing.job_title.toLowerCase().contains(criteria.toLowerCase())
            var requirementMatch = false

            for (requirement in jobListing.requirements) {
                if (requirement.toLowerCase().contains(criteria.toLowerCase())) {
                    requirementMatch = true
                    break
                }
            }

            if (titleMatch || requirementMatch) {
                matchingJobs.add(jobListing)
            }
        }
        return matchingJobs
    }

    public func get_job_applicants(job: JobListing): ArrayList<Resume> {
        /*
        This function is used to obtain candidate information,and return the candidate information that meets the requirements by calling the matches_requirements function.
        :param job: The position information,JobListing.
        :return: The candidate information that meets the requirements,ArrayList<Resume>.
        >>> jobMarketplace = JobMarketplace()
        >>> jobMarketplace.resumes = [Resume("Tom", ArrayList<String>(['skill1', 'skill2']), "experience")]
        >>> jobMarketplace.job_listings = [JobListing("Software Engineer", "ABC Company", ArrayList<String>(['skill1', 'skill2']))]
        >>> jobMarketplace.get_job_applicants(jobMarketplace.job_listings[0])
        [Resume("Tom", ArrayList<String>(['skill1', 'skill2']), "experience")]

        */
        let applicants = ArrayList<Resume>()
        for (resume in this.resumes) {
            if (JobMarketplace.matches_requirements(resume, job.requirements)) {
                applicants.add(resume)
            }
        }
        return applicants
    }

    public static func matches_requirements(resume: Resume, requirements: ArrayList<String>): Bool {
        /*
        This function checks if a resume meets all the job requirements.
        It verifies whether the resume contains all the skills specified in the job requirements.

        :param resume: The resume to be evaluated, Resume object containing candidate's skills
        :param requirements: The list of required skills for the job, ArrayList<String>
        :return: Bool value indicating if the resume meets all requirements (true if all requirements are satisfied, false otherwise)
        */
        for (requirement in requirements) {
            var found = false
            for (skill in resume.skills) {
                if (skill == requirement) {
                    found = true
                    break
                }
            }
            if (!found) {
                return false
            }
        }
        return true
    }
}

import std.collection.*
import std.math.pow

class KappaCalculator {

    /*
    This is a class as KappaCalculator, supporting to calculate Cohen's and Fleiss' kappa coefficient.
    */

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        /*
        Calculate the cohens kappa value of a k-dimensional matrix
        :param testData: The k-dimensional matrix that needs to calculate the cohens kappa value
        :param k: Int64, Matrix dimension
        :return:float, the cohens kappa value of the matrix
        >>> KappaCalculator.kappa(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([2, 1, 1]), ArrayList<Int64>([1, 2, 1]), ArrayList<Int64>([1, 1, 2])]), 3)
        0.25
        */

        var P0: Float64 = 0.0
        for (i in 0..k) {
            let row = testData.get(i).getOrThrow()
            let diagonal = row.get(i).getOrThrow()
            P0 += Float64(diagonal)
        }

        var xsumList = ArrayList<Float64>()
        var ysumList = ArrayList<Float64>()

        for (i in 0..k) {
            let row = testData.get(i).getOrThrow()
            var rowSum: Float64 = 0.0
            for (j in 0..k) {
                rowSum += Float64(row.get(j).getOrThrow())
            }
            xsumList.add(rowSum)
        }

        for (j in 0..k) {
            var colSum: Float64 = 0.0
            for (i in 0..k) {
                let row = testData.get(i).getOrThrow()
                colSum += Float64(row.get(j).getOrThrow())
            }
            ysumList.add(colSum)
        }

        var totalSum: Float64 = 0.0
        for (i in 0..k) {
            totalSum += xsumList.get(i).getOrThrow()
        }

        var Pe: Float64 = 0.0
        for (i in 0..k) {
            Pe += (ysumList.get(i).getOrThrow() * xsumList.get(i).getOrThrow()) / (totalSum * totalSum)
        }

        P0 = P0 / totalSum

        let cohens_coefficient = (P0 - Pe) / (1.0 - Pe)
        return cohens_coefficient
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        /*
        Calculate the fliss kappa value of an N * k matrix
        :param testData: Input data matrix, N * k
        :param N: Int64, Number of samples
        :param k: Int64, Number of categories
        :param n: Int64, Number of raters
        :return: Float64, fleiss kappa value
        >>> KappaCalculator.fleiss_kappa(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([0, 0, 0, 0, 14]),
        >>>                              ArrayList<Int64>([0, 2, 6, 4, 2]),
        >>>                              ArrayList<Int64>([0, 0, 3, 5, 6]),
        >>>                              ArrayList<Int64>([0, 3, 9, 2, 0]),
        >>>                              ArrayList<Int64>([2, 2, 8, 1, 1]),
        >>>                              ArrayList<Int64>([7, 7, 0, 0, 0]),
        >>>                              ArrayList<Int64>([3, 2, 6, 3, 0]),
        >>>                              ArrayList<Int64>([2, 5, 3, 2, 2]),
        >>>                              ArrayList<Int64>([6, 5, 2, 1, 0]),
        >>>                              ArrayList<Int64>([0, 2, 2, 3, 7])], 10, 5, 14)
        0.20993070442195522
        */

        var sum: Float64 = 0.0
        var P0: Float64 = 0.0

        for (i in 0..N) {
            let row = testData.get(i).getOrThrow()
            var temp: Float64 = 0.0
            for (j in 0..k) {
                let value = Float64(row.get(j).getOrThrow())
                sum += value
                temp += pow(value, 2)
            }
            temp -= Float64(n)
            temp /= Float64(n - 1) * Float64(n)
            P0 += temp
        }

        P0 = P0 / Float64(N)

        var ysumList = ArrayList<Float64>()
        for (j in 0..k) {
            var colSum: Float64 = 0.0
            for (i in 0..N) {
                let row = testData.get(i).getOrThrow()
                colSum += Float64(row.get(j).getOrThrow())
            }
            ysumList.add(colSum)
        }

        var Pe: Float64 = 0.0
        for (i in 0..k) {
            let proportion = ysumList.get(i).getOrThrow() / sum
            Pe += pow(proportion, 2)
        }

        let ans = (P0 - Pe) / (1.0 - Pe)
        return ans
    }
}

import std.collection.ArrayList
import std.regex.Regex

class LongestWord {

    /*
    This is a class allows to add words to a list and find the longest word in a given sentence by comparing the words with the ones in the word list.
    */

    let word_list: ArrayList<String>

    public init() {
        /*
        Initialize a list of word.
        */
        this.word_list = ArrayList<String>()
    }

    public func add_word(word: String): Unit {
        /*
        append the input word into this.word_list
        :param word: String, input word
        */
        this.word_list.add(word)
    }

    public func find_longest_word(sentence: String): String {
        /*
        Remove punctuation marks and split a sentence into a list of word. Find the longest splited word that is in the this.word_list.
        Words are strictly case sensitive.
        :param sentence: a sentence String
        :return String: longest splited word that is in the this.word_list. return '' if this.word_list is empty.
        >>> longestWord = LongestWord()
        >>> longestWord.add_word('A')
        >>> longestWord.add_word('aM')
        >>> longestWord.find_longest_word('I am a student.')
        'a'
        */
        var longest_word = ""
        var processed_sentence = sentence.toLower()

        // Remove punctuation using regex
        let punctuation_regex = Regex("[^a-zA-Z0-9\\s]")
        processed_sentence = punctuation_regex.replaceAll(processed_sentence, "")

        // Split the sentence into words
        let words = processed_sentence.split(" ")

        // Find the longest word that exists in word_list
        for (word in words) {
            if (word.size() > 0) {
                for (list_word in this.word_list) {
                    if (word == list_word.toLower() && word.size() > longest_word.size()) {
                        longest_word = word
                    }
                }
            }
        }

        return longest_word
    }
}

import std.collection.ArrayList
import std.collection.HashSet
import std.random.Random

class MahjongConnect {

    /*
    MahjongConnect is a class representing a game board for Mahjong Connect with features like creating the board, checking valid moves, finding paths, removing icons, and checking if the game is over.
    */

    let BOARD_SIZE: ArrayList<Int64>
    let ICONS: ArrayList<String>
    var board: ArrayList<ArrayList<String>>

    public init(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>) {
        /*
        initialize the board size and the icon list, create the game board
        :param BOARD_SIZE: list of two integer numbers, representing the number of rows and columns of the game board
        :param ICONS: list of String, representing the icons
        >>>mc = MahjongConnect(ArrayList<Int64>([4, 4]), ArrayList<String>(['a', 'b', 'c']))
        mc.BOARD_SIZE = [4, 4]
        mc.ICONS = ['a', 'b', 'c']
        mc.board = mc.create_board()
        */
        this.BOARD_SIZE = BOARD_SIZE
        this.ICONS = ICONS
        this.board = create_board(BOARD_SIZE, ICONS)
    }

    public static func create_board(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>): ArrayList<ArrayList<String>> {
        /*
        create the game board with the given board size and icons
        :return: 2-dimensional list, the game board
        >>> mc = MahjongConnect(ArrayList<Int64>([4, 4]), ArrayList<String>(['a', 'b', 'c']))
        >>> mc.create_board()
        mc.board = [['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a']]
        */
        let rng = Random()
        let rows = BOARD_SIZE.get(0).getOrThrow()
        let cols = BOARD_SIZE.get(1).getOrThrow()
        let board = ArrayList<ArrayList<String>>()

        for (i in 0..rows) {
            let row = ArrayList<String>()
            for (j in 0..cols) {
                let iconIndex = rng.nextInt64(ICONS.size)
                row.add(ICONS.get(iconIndex).getOrThrow())
            }
            board.add(row)
        }
        return board
    }

    public func is_valid_move(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        /*
        check if the move of two icons is valid (i.e. positions are within the game board range, the two positions are not the same, the two positions have the same icon, and there is a valid path between the two positions)
        :param pos1: position Tuple(x, y) of the first icon
        :param pos2: position Tuple(x, y) of the second icon
        :return:true or false ,representing whether the move of two icons is valid
        >>> mc = MahjongConnect(ArrayList<Int64>([4, 4]), ArrayList<String>(['a', 'b', 'c']))
        mc.board = [['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a']]
        >>> mc.is_valid_move((0, 0), (1, 0))
        true
        */
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        let rows = BOARD_SIZE.get(0).getOrThrow()
        let cols = BOARD_SIZE.get(1).getOrThrow()

        // Check if positions are within the game board range
        if (!(0 <= x1 && x1 < rows && 0 <= y1 && y1 < cols && 
              0 <= x2 && x2 < rows && 0 <= y2 && y2 < cols)) {
            return false
        }

        // Check if the two positions are the same
        if (pos1 == pos2) {
            return false
        }

        // Check if the two positions have the same icon
        if (board.get(x1).getOrThrow().get(y1).getOrThrow() != 
            board.get(x2).getOrThrow().get(y2).getOrThrow()) {
            return false
        }

        // Check if there is a valid path between the two positions
        if (!has_path(pos1, pos2)) {
            return false
        }

        return true
    }

    public func has_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        /*
        check if there is a path between two icons
        :param pos1: position Tuple(x, y) of the first icon
        :param pos2: position Tuple(x, y) of the second icon
        :return: true or false ,representing whether there is a path between two icons
        >>> mc = MahjongConnect(ArrayList<Int64>([4, 4]), ArrayList<String>(['a', 'b', 'c']))
        mc.board = [['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a']]
        >>> mc.has_path((0, 0), (1, 0))
        true
        */
        let visited = ArrayList<(Int64, Int64)>()
        let stack = ArrayList<(Int64, Int64)>()
        stack.add(pos1)
        let targetIcon = board.get(pos1.0).getOrThrow().get(pos1.1).getOrThrow()

        while (stack.size > 0) {
            let current_pos = stack.remove(at: stack.size - 1).getOrThrow()
            if (current_pos == pos2) {
                return true
            }

            if (contains(visited, current_pos)) {
                continue
            }

            visited.add(current_pos)
            let (x, y) = current_pos

            // Check adjacent positions (up, down, left, right)
            let directions = ArrayList<(Int64, Int64)>()
            directions.add((0, 1))
            directions.add((0, -1))
            directions.add((1, 0))
            directions.add((-1, 0))

            for (dir in directions) {
                let (dx, dy) = dir
                let new_x = x + dx
                let new_y = y + dy
                let rows = BOARD_SIZE.get(0).getOrThrow()
                let cols = BOARD_SIZE.get(1).getOrThrow()

                if (0 <= new_x && new_x < rows && 0 <= new_y && new_y < cols) {
                    let new_pos = (new_x, new_y)
                    if (!contains(visited, new_pos)) {
                        let currentIcon = board.get(new_x).getOrThrow().get(new_y).getOrThrow()
                        if (currentIcon == targetIcon) {
                            stack.add(new_pos)
                        }
                    }
                }
            }
        }

        return false
    }

    public static func contains(visited: ArrayList<(Int64, Int64)>, pos: (Int64, Int64)): Bool {
        /*
        check if the position is in the visited list
        :param visited: list of position tuples, representing the visited positions
        :param pos: position tuple, representing the position to be checked
        :return: true or false, representing whether the position is in the visited list
        */
        for (v in visited) {
            if (v == pos) {
                return true
            }
        }
        return false
    }

    public func remove_icons(pos1: (Int64, Int64), pos2: (Int64, Int64)): Unit {
        /*
        remove the connected icons on the game board
        :param pos1: position tuple(x, y) of the first icon to be removed
        :param pos2: position tuple(x, y) of the second icon to be removed
        :return: Unit
        >>> mc = MahjongConnect(ArrayList<Int64>([4, 4]), ArrayList<String>(['a', 'b', 'c']))
        mc.board = [['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a']]
        >>> mc.remove_icons((0, 0), (1, 0))
        mc.board = [[' ', 'b', 'c', 'a'],
                    [' ', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a']]
        */
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        board.get(x1).getOrThrow().set(y1, " ")
        board.get(x2).getOrThrow().set(y2, " ")
    }

    public func is_game_over(): Bool {
        /*
        Check if the game is over (i.e., if there are no more icons on the game board)
        :return: true or false ,representing whether the game is over
        >>> mc = MahjongConnect(ArrayList<Int64>([4, 4]), ArrayList<String>(['a', 'b', 'c']))
        >>> mc.board = [[' ', ' ', ' ', ' '],
        >>>         [' ', ' ', ' ', ' '],
        >>>         [' ', ' ', ' ', ' '],
        >>>         [' ', ' ', ' ', ' ']]
        >>> mc.is_game_over()
        true
        */
        for (row in board) {
            for (icon in row) {
                if (icon != " ") {
                    return false
                }
            }
        }
        return true
    }
}

class Manacher {

    /*
    This is a class that implements a manacher algorithm to find the Longest palindromic substring in a given string.
    */

    let input_string: String

    public init(input_string: String) {
        /*
        Initializes the Manacher class with the given input_string.
        :param input_string: The input_string to be searched, String.
        */
        this.input_string = input_string
    }

    public func palindromic_length(center: Int64, diff: Int64, string: String): Int64 {
        /*
        Recursively calculates the length of the palindromic substring based on a given center, difference value, and input string.
        :param center: The center of the palindromic substring, Int64.
        :param diff: The difference between the center and the current position, Int64.
        :param string: The string to be searched, String.
        :return: The length of the palindromic substring, Int64.
        >>> manacher = Manacher('ababa')
        >>> manacher.palindromic_length(2, 1, 'a|b|a|b|a')
        2

        */
        if (center - diff == -1 || center + diff == string.size || string[center - diff] != string[center + diff]) {
            return 0
        }
        return 1 + palindromic_length(center, diff + 1, string)
    }

    public func palindromic_string(): String {
        /*
        Finds the longest palindromic substring in the given string.
        :return: The longest palindromic substring, String.
        >>> manacher = Manacher('ababaxse')
        >>> manacher.palindromic_string()
        'ababa'

        */
        var max_length: Int64 = 0
        var new_input_string: String = ""
        var output_string: String = ""
        var start: Int64 = 0

        // Preprocess the string by adding separators
        for (i in 0..this.input_string.size - 1) {
            if (i == this.input_string.size - 1) {
                new_input_string += this.input_string[i]
            } else {
                new_input_string += "${this.input_string[i]}|"
            }
        }

        // Find the longest palindromic substring
        for (i in 0..new_input_string.size - 1) {
            let length = palindromic_length(i, 1, new_input_string)

            if (max_length < length) {
                max_length = length
                start = i
            }
        }

        // Extract the palindromic substring and remove separators
        for (i in start - max_length..start + max_length) {
            if (new_input_string[i] != '|') {
                output_string += new_input_string[i]
            }
        }

        return output_string
    }
}

import std.collection.ArrayList
import std.math.abs

class MetricsCalculator {

    /*
    The class calculates precision, recall, F1 score, and accuracy based on predicted and true labels.
    */

    var true_positives: Int64
    var false_positives: Int64
    var false_negatives: Int64
    var true_negatives: Int64

    public init() {
        /*
        Initialize the number of all four samples to 0
        */
        this.true_positives = 0
        this.false_positives = 0
        this.false_negatives = 0
        this.true_negatives = 0
    }

    public func update(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Unit {
        /*
        Update the number of all four samples(true_positives, false_positives, false_negatives, true_negatives)
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: None, change the number of corresponding samples
        >>> mc = MetricsCalculator()
        >>> mc.update(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        (this.true_positives, this.false_positives, this.false_negatives, this.true_negatives) = (1, 1, 1, 1)
        */
        for (i in 0..predicted_labels.size()) {
            let predicted = predicted_labels[i]
            let true_label = true_labels[i]
            if (predicted == 1 && true_label == 1) {
                this.true_positives += 1
            } else if (predicted == 1 && true_label == 0) {
                this.false_positives += 1
            } else if (predicted == 0 && true_label == 1) {
                this.false_negatives += 1
            } else if (predicted == 0 && true_label == 0) {
                this.true_negatives += 1
            }
        }
    }

    public func precision(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate precision
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.precision(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        this.update(predicted_labels, true_labels)
        if (this.true_positives + this.false_positives == 0) {
            return 0.0
        }
        return Float64(this.true_positives) / Float64(this.true_positives + this.false_positives)
    }

    public func recall(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate recall
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.recall(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        this.update(predicted_labels, true_labels)
        if (this.true_positives + this.false_negatives == 0) {
            return 0.0
        }
        return Float64(this.true_positives) / Float64(this.true_positives + this.false_negatives)
    }

    public func f1_score(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate f1 score, which is the harmonic mean of precision and recall
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.f1_score(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        this.update(predicted_labels, true_labels)
        let precision_val = this.precision(predicted_labels, true_labels)
        let recall_val = this.recall(predicted_labels, true_labels)
        if (precision_val + recall_val == 0.0) {
            return 0.0
        }
        return (2.0 * precision_val * recall_val) / (precision_val + recall_val)
    }

    public func accuracy(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate accuracy
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.accuracy(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        this.update(predicted_labels, true_labels)
        let total = this.true_positives + this.true_negatives + this.false_positives + this.false_negatives
        if (total == 0) {
            return 0.0
        }
        return Float64(this.true_positives + this.true_negatives) / Float64(total)
    }
}

import std.collection.ArrayList
import std.math.abs

class MetricsCalculator2 {

    /*
    The class provides to calculate Mean Reciprocal Rank (MRR) and Mean Average Precision (MAP) based on input data, where MRR measures the ranking quality and MAP measures the average precision.
    */

    public init() {}

    public static func mrr(data: Any): (Float64, ArrayList<Float64>) {
        /*
        compute the MRR of the input data. MRR is a widely used evaluation index. It is the mean of reciprocal rank.
        :param data: the data must be a tuple, list 0,1,eg.([1,0,...],5).  In each tuple (actual result,ground truth num),ground truth num is the total ground num.
         ([1,0,...],5),
        or list of tuple eg. [([1,0,1,...],5),([1,0,...],6),([0,0,...],5)].
        1 stands for a correct answer, 0 stands for a wrong answer.
        :return: if input data is list, return the recall of this list. if the input data is list of list, return the
        average recall on all list. The second return value is a list of precision for each input.
        >>> MetricsCalculator2.mrr((ArrayList<Int64>([1, 0, 1, 0]), 4))
        >>> MetricsCalculator2.mrr([(ArrayList<Int64>([1, 0, 1, 0]), 4), (ArrayList<Int64>([0, 1, 0, 1]), 4)])
        1.0, [1.0]
        0.75, [1.0, 0.5]
        */

        // Handle single tuple input
        if (data is (ArrayList<Int64>, Int64)) {
            let (subList, totalNum) = data as (ArrayList<Int64>, Int64)

            if (totalNum == 0) {
                return (0.0, ArrayList<Float64>([0.0]))
            }

            // Find first relevant item (value 1)
            var firstRelevantRank = -1
            for (i in 0..subList.size) {
                if (subList[i] == 1) {
                    firstRelevantRank = i + 1  // 1-based ranking
                    break
                }
            }

            if (firstRelevantRank == -1) {
                return (0.0, ArrayList<Float64>([0.0]))
            }

            let mr = 1.0 / Float64(firstRelevantRank)
            return (mr, ArrayList<Float64>([mr]))
        }

        // Handle list of tuples input
        if (data is ArrayList<(ArrayList<Int64>, Int64)>) {
            let dataList = data as ArrayList<(ArrayList<Int64>, Int64)>

            if (dataList.size == 0) {
                return (0.0, ArrayList<Float64>([0.0]))
            }

            let separateResult = ArrayList<Float64>()
            var sumMRR = 0.0

            for (item in dataList) {
                let (subList, totalNum) = item

                if (totalNum == 0) {
                    separateResult.add(0.0)
                    continue
                }

                // Find first relevant item (value 1)
                var firstRelevantRank = -1
                for (i in 0..subList.size) {
                    if (subList[i] == 1) {
                        firstRelevantRank = i + 1  // 1-based ranking
                        break
                    }
                }

                if (firstRelevantRank == -1) {
                    separateResult.add(0.0)
                } else {
                    let mr = 1.0 / Float64(firstRelevantRank)
                    separateResult.add(mr)
                    sumMRR += mr
                }
            }

            let meanMRR = sumMRR / Float64(separateResult.size)
            return (meanMRR, separateResult)
        }

        // Invalid input type
        throw Exception("the input must be a tuple(ArrayList<Int64>, Int64) or an ArrayList of tuple")
    }

    public static func map(data: Any): (Float64, ArrayList<Float64>) {
        /*
        compute the MAP of the input data. MAP is a widely used evaluation index. It is the mean of AP (average precision).
        :param data: the data must be a tuple, list 0,1,eg.([1,0,...],5).  In each tuple (actual result,ground truth num),ground truth num is the total ground num.
         ([1,0,...],5),
        or list of tuple eg. [([1,0,1,...],5),([1,0,...],6),([0,0,...],5)].
        1 stands for a correct answer, 0 stands for a wrong answer.
        :return: if input data is list, return the recall of this list. if the input data is list of list, return the
        average recall on all list. The second return value is a list of precision for each input.
        >>> MetricsCalculator2.map((ArrayList<Int64>([1, 0, 1, 0]), 4))
        >>> MetricsCalculator2.map([(ArrayList<Int64>([1, 0, 1, 0]), 4), (ArrayList<Int64>([0, 1, 0, 1]), 4)])
        0.41666666666666663, [0.41666666666666663]
        0.3333333333333333, [0.41666666666666663, 0.25]
        */

        // Handle single tuple input
        if (data is (ArrayList<Int64>, Int64)) {
            let (subList, totalNum) = data as (ArrayList<Int64>, Int64)

            if (totalNum == 0) {
                return (0.0, ArrayList<Float64>([0.0]))
            }

            var relevantCount = 0
            var precisionSum = 0.0

            for (i in 0..subList.size) {
                if (subList[i] == 1) {
                    relevantCount += 1
                    let precision = Float64(relevantCount) / Float64(i + 1)
                    precisionSum += precision
                }
            }

            if (relevantCount == 0) {
                return (0.0, ArrayList<Float64>([0.0]))
            }

            let ap = precisionSum / Float64(totalNum)
            return (ap, ArrayList<Float64>([ap]))
        }

        // Handle list of tuples input
        if (data is ArrayList<(ArrayList<Int64>, Int64)>) {
            let dataList = data as ArrayList<(ArrayList<Int64>, Int64)>

            if (dataList.size == 0) {
                return (0.0, ArrayList<Float64>([0.0]))
            }

            let separateResult = ArrayList<Float64>()
            var sumMAP = 0.0

            for (item in dataList) {
                let (subList, totalNum) = item

                if (totalNum == 0) {
                    separateResult.add(0.0)
                    continue
                }

                var relevantCount = 0
                var precisionSum = 0.0

                for (i in 0..subList.size) {
                    if (subList[i] == 1) {
                        relevantCount += 1
                        let precision = Float64(relevantCount) / Float64(i + 1)
                        precisionSum += precision
                    }
                }

                if (relevantCount == 0) {
                    separateResult.add(0.0)
                } else {
                    let ap = precisionSum / Float64(totalNum)
                    separateResult.add(ap)
                    sumMAP += ap
                }
            }

            let meanMAP = sumMAP / Float64(separateResult.size)
            return (meanMAP, separateResult)
        }

        // Invalid input type
        throw Exception("the input must be a tuple(ArrayList<Int64>, Int64) or an ArrayList of tuple")
    }
}

import std.collection.ArrayList
import std.random.Random
import std.convert.Parsable

class MinesweeperGame {

    /*
    This is a class that implements mine sweeping games including minesweeping and winning judgment.
    */

    let n: Int64
    let k: Int64
    var minesweeper_map: ArrayList<ArrayList<String>>
    var player_map: ArrayList<ArrayList<String>>
    var score: Int64

    public init(n: Int64, k: Int64) {
        /*
        Initializes the MinesweeperGame class with the size of the board and the number of mines.
        :param n: The size of the board, Int64.
        :param k: The number of mines, Int64.
        */
        this.n = n
        this.k = k
        this.minesweeper_map = generate_mine_sweeper_map(n, k)
        this.player_map = generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        /*
        Generates a minesweeper map with the given size of the board and the number of mines,the given parameter n is the size of the board,the size of the board is n*n,the parameter k is the number of mines,'X' represents the mine,other numbers represent the number of mines around the position.
        :return: The minesweeper map, ArrayList<ArrayList<String>>.
        >>> MinesweeperGame.generate_mine_sweeper_map(3)
        [['X', '1', '0'], ['1', '1', '0'], ['0', '0', '0']]

        */
        let rng = Random()
        let arr = ArrayList<ArrayList<String>>()

        // Initialize the board with '0'
        for (i in 0..n) {
            let row = ArrayList<String>()
            for (j in 0..n) {
                row.add("0")
            }
            arr.add(row)
        }

        // Place mines randomly
        var minesPlaced = 0
        while (minesPlaced < k) {
            let x = rng.nextInt64(n)
            let y = rng.nextInt64(n)

            if (arr[y][x] != "X") {
                arr[y][x] = "X"
                minesPlaced += 1

                // Update adjacent cells
                // Right neighbor
                if (x >= 0 && x <= n-2 && y >= 0 && y <= n-1) {
                    if (arr[y][x+1] != "X") {
                        let count = Int64.parse(arr[y][x+1])
                        arr[y][x+1] = (count + 1).toString()
                    }
                }
                // Left neighbor
                if (x >= 1 && x <= n-1 && y >= 0 && y <= n-1) {
                    if (arr[y][x-1] != "X") {
                        let count = Int64.parse(arr[y][x-1])
                        arr[y][x-1] = (count + 1).toString()
                    }
                }
                // Top-left neighbor
                if (x >= 1 && x <= n-1 && y >= 1 && y <= n-1) {
                    if (arr[y-1][x-1] != "X") {
                        let count = Int64.parse(arr[y-1][x-1])
                        arr[y-1][x-1] = (count + 1).toString()
                    }
                }
                // Top-right neighbor
                if (x >= 0 && x <= n-2 && y >= 1 && y <= n-1) {
                    if (arr[y-1][x+1] != "X") {
                        let count = Int64.parse(arr[y-1][x+1])
                        arr[y-1][x+1] = (count + 1).toString()
                    }
                }
                // Top neighbor
                if (x >= 0 && x <= n-1 && y >= 1 && y <= n-1) {
                    if (arr[y-1][x] != "X") {
                        let count = Int64.parse(arr[y-1][x])
                        arr[y-1][x] = (count + 1).toString()
                    }
                }
                // Bottom-right neighbor
                if (x >= 0 && x <= n-2 && y >= 0 && y <= n-2) {
                    if (arr[y+1][x+1] != "X") {
                        let count = Int64.parse(arr[y+1][x+1])
                        arr[y+1][x+1] = (count + 1).toString()
                    }
                }
                // Bottom-left neighbor
                if (x >= 1 && x <= n-1 && y >= 0 && y <= n-2) {
                    if (arr[y+1][x-1] != "X") {
                        let count = Int64.parse(arr[y+1][x-1])
                        arr[y+1][x-1] = (count + 1).toString()
                    }
                }
                // Bottom neighbor
                if (x >= 0 && x <= n-1 && y >= 0 && y <= n-2) {
                    if (arr[y+1][x] != "X") {
                        let count = Int64.parse(arr[y+1][x])
                        arr[y+1][x] = (count + 1).toString()
                    }
                }
            }
        }

        return arr
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        /*
        Generates a player map with the given size of the board, the given parameter n is the size of the board,the size of the board is n*n,the parameter k is the number of mines,'-' represents the unknown position.
        :return: The player map, ArrayList<ArrayList<String>>.
        >>> MinesweeperGame.generate_playerMap(3)
        [['-', '-', '-'], ['-', '-', '-'], ['-', '-', '-']]

        */
        let arr = ArrayList<ArrayList<String>>()

        for (i in 0..n) {
            let row = ArrayList<String>()
            for (j in 0..n) {
                row.add("-")
            }
            arr.add(row)
        }

        return arr
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        /*
        Checks whether the player has won the game,if there are just mines in the player map,return true,otherwise return false.
        :return: true if the player has won the game, false otherwise.
        >>> minesweeper_game = MinesweeperGame(3, 1)
        >>> minesweeper_game.minesweeper_map = ArrayList<ArrayList<String>>([ArrayList<String>(['X', '1', '0']), ArrayList<String>(['1', '1', '0']), ArrayList<String>(['0', '0', '0'])])
        >>> minesweeper_game.player_map = ArrayList<ArrayList<String>>([ArrayList<String>(['-', '-', '-']), ArrayList<String>(['-', '-', '-']), ArrayList<String>(['-', '-', '-'])])
        >>> minesweeper_game.check_won(minesweeper_game.player_map)
        false

        */
        for (i in 0..this.n) {
            for (j in 0..this.n) {
                if (map[i][j] == "-" && this.minesweeper_map[i][j] != "X") {
                    return false
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        /*
        Sweeps the given position.
        :param x: The x coordinate of the position, Int64.
        :param y: The y coordinate of the position, Int64.
        :return: true if the player has won the game, false otherwise,if the game still continues, return the player map, ArrayList<ArrayList<String>>.
        >>> minesweeper_game = MinesweeperGame(3, 1)
        >>> minesweeper_game.minesweeper_map = ArrayList<ArrayList<String>>([ArrayList<String>(['X', '1', '0']), ArrayList<String>(['1', '1', '0']), ArrayList<String>(['0', '0', '0'])])
        >>> minesweeper_game.player_map = ArrayList<ArrayList<String>>([ArrayList<String>(['-', '-', '-']), ArrayList<String>(['-', '-', '-']), ArrayList<String>(['-', '-', '-'])])
        >>> minesweeper_game.sweep(1, 1)
        [['-', '-', '-'], ['-', 1, '-'], ['-', '-', '-']]

        */
        if (this.minesweeper_map[x][y] == "X") {
            return false
        } else {
            this.player_map[x][y] = this.minesweeper_map[x][y]
            this.score += 1
            if (this.check_won(this.player_map) == true) {
                return true
            }
            return this.player_map
        }
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.time.DateTime
import std.math.abs

class MovieBookingSystem {

    /*
    this is a class as movie booking system, which allows to add movies, book tickets and check the available movies within a given time range. 
    */

    let movies: ArrayList<HashMap<String, Any>>

    public init() {
        /*
        Initialize movies contains the information about movies
        >>> system.movies
        [{'name': 'Batman', 'price': 49.9, 'start_time': DateTime.parse("2023/01/01 17:05", "yyyy/MM/dd HH:mm"), 'end_time': DateTime.parse("2023/01/01 19:25", "yyyy/MM/dd HH:mm"),
        'seats': ArrayList<ArrayList<Int64>>([ArrayList<Int64>([0, 0, 0]),
            ArrayList<Int64>([0, 0, 0]),
            ArrayList<Int64>([0, 0, 0])
            ])}]
        */
        movies = ArrayList<HashMap<String, Any>>()
    }

    public func add_movie(name: String, price: Float64, start_time: String, end_time: String, n: Int64): Unit {
        /*
        Add a new movie into this.movies
        :param name: String, movie name
        :param price: Float64, price for one ticket
        :param start_time: String
        :param end_time: String
        :param n: Int64, the size of seats(n*n)
        >>> system.add_movie('Batman', 49.9, '2023/01/01 17:05', '2023/01/01 19:25', 3)
        >>> system.movies
        [{'name': 'Batman', 'price': 49.9, 'start_time': DateTime.parse("2023/01/01 17:05", "yyyy/MM/dd HH:mm"), 'end_time': DateTime.parse("2023/01/01 19:25", "yyyy/MM/dd HH:mm"),
        'seats': ArrayList<ArrayList<Int64>>([ArrayList<Int64>([0, 0, 0]),
            ArrayList<Int64>([0, 0, 0]),
            ArrayList<Int64>([0, 0, 0])
            ])}]
        */
        let movie = HashMap<String, Any>()
        movie["name"] = name
        movie["price"] = price
        movie["start_time"] = DateTime.parse(start_time, "yyyy/MM/dd HH:mm")
        movie["end_time"] = DateTime.parse(end_time, "yyyy/MM/dd HH:mm")

        let seats = ArrayList<ArrayList<Int64>>()
        for (i in 0..n) {
            let row = ArrayList<Int64>()
            for (j in 0..n) {
                row.add(0)
            }
            seats.add(row)
        }
        movie["seats"] = seats

        movies.add(movie)
    }

    public func book_ticket(name: String, seats_to_book: ArrayList<ArrayList<Int64>>): String {
        /*
        Book tickets for a movie. Change the seats value in this.movies if book successfully.
        :param name: String, movie name
        :param seats_to_book: ArrayList<ArrayList<Int64>>, representing seats to book [[row1, col1], [row2, col2], ...]
        :return: String, booking status message. "Movie not found." for no such movie.
                "Booking success." for successfully booking, or "Booking failed." otherwise
        >>> system.add_movie('Batman', 49.9, '2023/01/01 17:05', '2023/01/01 19:25', 3)
        >>> system.book_ticket('Batman', ArrayList<ArrayList<Int64>>([ArrayList<Int64>([0, 0]), ArrayList<Int64>([0, 1])]))
        'Booking success.'
        >>> system.book_ticket('Batman', ArrayList<ArrayList<Int64>>([ArrayList<Int64>([0, 0])]))
        'Booking failed.'
        >>> system.book_ticket('batman', ArrayList<ArrayList<Int64>>([ArrayList<Int64>([0, 0])]))
        'Movie not found.'
        */
        for (movie in movies) {
            let movieName = movie["name"]
            if (movieName is String && movieName == name) {
                let seats = movie["seats"]
                if (seats is ArrayList<ArrayList<Int64>>) {
                    // Check if all seats are available
                    for (seat in seats_to_book) {
                        if (seat.size() < 2) {
                            return "Booking failed."
                        }
                        let row = seat[0]
                        let col = seat[1]
                        if (row >= seats.size() || col >= seats[row].size()) {
                            return "Booking failed."
                        }
                        if (seats[row][col] != 0) {
                            return "Booking failed."
                        }
                    }

                    // Book all seats
                    for (seat in seats_to_book) {
                        let row = seat[0]
                        let col = seat[1]
                        seats[row][col] = 1
                    }
                    return "Booking success."
                }
            }
        }
        return "Movie not found."
    }

    public func available_movies(start_time: String, end_time: String): ArrayList<String> {
        /*
        Get a list of available movies within the specified time range
        :param start_time: String, start time in yyyy/MM/dd HH:mm format
        :param end_time: String, end time in yyyy/MM/dd HH:mm format
        :return: ArrayList<String>, names of available movies
        >>> system.add_movie('Batman', 49.9, '2023/01/01 17:05', '2023/01/01 19:25', 3)
        >>> system.available_movies('2023/01/01 12:00', '2023/01/01 22:00')
        ['Batman']
        */
        let availableMovies = ArrayList<String>()
        let startTime = DateTime.parse(start_time, "yyyy/MM/dd HH:mm")
        let endTime = DateTime.parse(end_time, "yyyy/MM/dd HH:mm")

        for (movie in movies) {
            let movieStart = movie["start_time"]
            let movieEnd = movie["end_time"]
            if (movieStart is DateTime && movieEnd is DateTime) {
                if (startTime <= movieStart && movieEnd <= endTime) {
                    let movieName = movie["name"]
                    if (movieName is String) {
                        availableMovies.add(movieName)
                    }
                }
            }
        }

        return availableMovies
    }
}

import std.random.Random
import std.collection.ArrayList

class MusicPlayer {

    /*
    This is a class as a music player that provides to play, stop, add songs, remove songs, set volume, shuffle, and switch to the next or previous song.
    */

    var playlist: ArrayList<String>
    var current_song: Option<String>
    var volume: Int64

    public init() {
        /*
        Initializes the music player with an empty playlist, no current song, and a default volume of 50.
        */
        this.playlist = ArrayList<String>()
        this.current_song = None
        this.volume = 50
    }

    public func add_song(song: String): Unit {
        /*
        Adds a song to the playlist.
        :param song: The song to add to the playlist, String.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.add_song("song1")
        >>> musicPlayer.playlist
        ['song1']

        */
        this.playlist.add(song)
    }

    public func remove_song(song: String): Unit {
        /*
        Removes a song from the playlist.
        :param song: The song to remove from the playlist, String.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.remove_song("song1")
        >>> musicPlayer.playlist
        ['song2']

        */
        if (this.playlist.contains(song)) {
            this.playlist.remove(song)
            if (this.current_song == Some(song)) {
                this.stop()
            }
        }
    }

    public func play(): Option<String> {
        /*
        Plays the current song in the playlist.
        :return: The current song in the playlist, or "False" if there is no current song, or None if the playlist is empty, Option<String>.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.current_song = "song1"
        >>> musicPlayer.play()
        'song1'

        */
        if (this.playlist.size > 0) {
            if (let Some(current) = this.current_song) {
                return Some(current)
            } else {
                this.current_song = Some(this.playlist[0])
                return this.current_song
            }
        } else {
            return None
        }
    }

    public func stop(): Bool {
        /*
        Stops the current song in the playlist.
        :return: true if the current song was stopped, false if there was no current song.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.current_song = "song1"
        >>> musicPlayer.stop()
        true

        */
        if (let Some(_) = this.current_song) {
            this.current_song = None
            return true
        } else {
            return false
        }
    }

    public func switch_song(): Bool {
        /*
        Switches to the next song in the playlist.
        :return: true if the next song was switched to, false if there was no next song.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.current_song = "song1"
        >>> musicPlayer.switch_song()
        true

        */
        if (let Some(current) = this.current_song) {
            let current_index = this.playlist.indexOf(current)
            if (current_index < this.playlist.size - 1) {
                this.current_song = Some(this.playlist[current_index + 1])
                return true
            } else {
                return false
            }
        } else {
            return false
        }
    }

    public func previous_song(): Bool {
        /*
        Switches to the previous song in the playlist.
        :return: true if the previous song was switched to, false if there was no previous song.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.current_song = "song2"
        >>> musicPlayer.previous_song()
        true

        */
        if (let Some(current) = this.current_song) {
            let current_index = this.playlist.indexOf(current)
            if (current_index > 0) {
                this.current_song = Some(this.playlist[current_index - 1])
                return true
            } else {
                return false
            }
        } else {
            return false
        }
    }

    public func set_volume(volume: Int64): Bool {
        /*
        Sets the volume of the music player,ifthe volume is between 0 and 100 is valid.
        :param volume: The volume to set the music player to,Int64.
        :return: true if the volume was set, false if the volume was invalid.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.set_volume(50)
        true
        >>> musicPlayer.volume
        50

        */
        if (0 <= volume && volume <= 100) {
            this.volume = volume
            return true
        } else {
            return false
        }
    }

    public func shuffle(): Bool {
        /*
        Shuffles the playlist.
        :return: true if the playlist was shuffled, false if the playlist was empty.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.shuffle()
        true

        */
        if (this.playlist.size > 0) {
            let random = Random()
            let shuffled_list = ArrayList<String>()
            let temp_list = ArrayList<String>()

            // Copy all elements to temp list
            for (song in this.playlist) {
                temp_list.add(song)
            }

            // Shuffle by randomly selecting elements
            while (temp_list.size > 0) {
                let random_index = random.nextInt64(temp_list.size)
                shuffled_list.add(temp_list[random_index])
                temp_list.remove(at: random_index)
            }

            // Replace original playlist with shuffled version
            this.playlist.clear()
            for (song in shuffled_list) {
                this.playlist.add(song)
            }
            return true
        } else {
            return false
        }
    }
}

import std.collection.ArrayList

class NLPDataProcessor {

    /*
    The class processes NLP data by removing stop words from a list of strings using a pre-defined stop word list.
    */

    public func construct_stop_word_list(): ArrayList<String> {
        /*
        Construct a stop word list including 'a', 'an', 'the'.
        :return: a list of stop words
        >>> nlp_data_processor = NLPDataProcessor()
        >>> nlp_data_processor.construct_stop_word_list()
        ['a', 'an', 'the']
        */
        var stop_word_list = ArrayList<String>()
        stop_word_list.add("a")
        stop_word_list.add("an")
        stop_word_list.add("the")
        return stop_word_list
    }

    public func remove_stop_words(string_list: ArrayList<String>, stop_word_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        /*
        Remove all the stop words from the list of strings.
        :param string_list: a list of strings
        :param stop_word_list: a list of stop words
        :return: a list of words without stop words
        >>> nlp_data_processor = NLPDataProcessor()
        >>> nlp_data_processor.process(ArrayList<String>(['This is a test.']), ArrayList<String>(['a', 'an', 'the']))
        [['This', 'is', 'test.']]
        */
        var answer = ArrayList<ArrayList<String>>()

        for (string in string_list) {
            var string_split = string.split(" ")
            var filtered_words = ArrayList<String>()

            for (word in string_split) {
                var is_stop_word = false
                for (stop_word in stop_word_list) {
                    if (word == stop_word) {
                        is_stop_word = true
                        break
                    }
                }
                if (!is_stop_word) {
                    filtered_words.add(word)
                }
            }
            answer.add(filtered_words)
        }
        return answer
    }

    public func process(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        /*
        Construct a stop word list including 'a', 'an', 'the', and remove all the stop words from the list of strings.
        :param string_list: a list of strings
        :return: a list of words without stop words
        >>> nlp_data_processor = NLPDataProcessor()
        >>> NLPDataProcessor.process(ArrayList<String>(['This is a test.']))
        [['This', 'is', 'test.']]
        */
        var stop_word_list = construct_stop_word_list()
        var words_list = remove_stop_words(string_list, stop_word_list)
        return words_list
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.regex.Regex
import std.sort.sort
import std.unicode.UnicodeStringExtension

class NLPDataProcessor2 {

    /*
    The class processes NLP data by extracting words from a list of strings, calculating the frequency of each word, and returning the top 5 most frequent words.
    */

    public func process_data(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        /*
        keep only English letters and spaces in the string, then convert the string to lower case, and then split the string into a list of words.
        :param string_list: a list of strings
        :return: words_list: a list of words lists
        >>> NLPDataProcessor.process_data(ArrayList<String>(['This is a test.']))
        [['this', 'is', 'a', 'test']]
        */
        let words_list = ArrayList<ArrayList<String>>()
        let non_english_regex = Regex("[^a-zA-Z\\s]+")

        for (string in string_list) {
            // Remove non-English letters and convert to lowercase
            let processed_string = non_english_regex.replaceAll(string, "").toLowerCase()
            // Split the string into words
            let words = processed_string.split(" ")
            let word_list = ArrayList<String>()
            for (word in words) {
                if (word.size > 0) {
                    word_list.add(word)
                }
            }
            words_list.add(word_list)
        }
        return words_list
    }

    public func calculate_word_frequency(words_list: ArrayList<ArrayList<String>>): HashMap<String, Int64> {
        /*
        Calculate the word frequency of each word in the list of words list, and sort the word frequency dictionary by value in descending order.
        :param words_list: a list of words lists
        :return: top 5 word frequency dictionary, a dictionary of word frequency, key is word, value is frequency
        >>> NLPDataProcessor.calculate_word_frequency(ArrayList<ArrayList<String>>([ArrayList<String>(['this', 'is', 'a', 'test']), ArrayList<String>(['this', 'is', 'another', 'test'])]))
        {'this': 2, 'is': 2, 'test': 2, 'a': 1, 'another': 1}
        */
        let word_frequency = HashMap<String, Int64>()

        for (word_list in words_list) {
            for (word in word_list) {
                if (word_frequency.contains(word)) {
                    word_frequency[word] = word_frequency[word] + 1
                } else {
                    word_frequency.add(word, 1)
                }
            }
        }

        // Convert HashMap to ArrayList of tuples for sorting
        let freq_list = ArrayList<(String, Int64)>()
        for ((key, value) in word_frequency) {
            freq_list.add((key, value))
        }

        // Sort by value in descending order
        sort(freq_list, (a: (String, Int64), b: (String, Int64)) => b.1.compare(a.1))

        // Take top 5 and create result HashMap
        let top_5_word_frequency = HashMap<String, Int64>()
        let count = if (freq_list.size < 5) { freq_list.size } else { 5 }
        for (i in 0..count) {
            let (word, freq) = freq_list[i]
            top_5_word_frequency.add(word, freq)
        }

        return top_5_word_frequency
    }

    public func process(string_list: ArrayList<String>): HashMap<String, Int64> {
        /*
        keep only English letters and spaces in the string, then convert the string to lower case, and then split the string into a list of words. Calculate the word frequency of each word in the list of words list, and sort the word frequency dictionary by value in descending order.
        :param string_list: a list of strings
        :return: top 5 word frequency dictionary, a dictionary of word frequency, key is word, value is frequency
        >>> NLPDataProcessor.process(ArrayList<String>(['This is a test.', 'This is another test.']))
        {'this': 2, 'is': 2, 'test': 2, 'a': 1, 'another': 1}
        */
        let words_list = this.process_data(string_list)
        let word_frequency_dict = this.calculate_word_frequency(words_list)
        return word_frequency_dict
    }
}

import std.convert.Formattable
import std.convert.Parsable
import std.convert.RadixConvertible

class NumberConverter {

    /*
    The class allows to convert  decimal to binary, octal and hexadecimal repectively and contrarily
    */

    public static func decimal_to_binary(decimal_num: Int64): String {
        /*
        Convert a number from decimal format to binary format.
        :param decimal_num: Int64, decimal number
        :return: String, the binary representation of an integer.
        >>> NumberConverter.decimal_to_binary(42423)
        '1010010110110111'
        */
        return decimal_num.format("b")
    }

    public static func binary_to_decimal(binary_num: String): Int64 {
        /*
        Convert a number from binary format to decimal format.
        :param binary_num: String, binary number
        :return: Int64, the decimal representation of binary number str.
        >>> NumberConverter.binary_to_decimal('1010010110110111')
        42423
        */
        return Int64.parse(binary_num, radix: 2)
    }

    public static func decimal_to_octal(decimal_num: Int64): String {
        /*
        Convert a number from decimal format to octal format.
        :param decimal_num: Int64, decimal number
        :return: String, the octal representation of an integer.
        >>> NumberConverter.decimal_to_octal(42423)
        '122667'
        */
        return decimal_num.format("o")
    }

    public static func octal_to_decimal(octal_num: String): Int64 {
        /*
        Convert a number from octal format to decimal format.
        :param octal_num: String, octal number
        :return: Int64, the decimal representation of octal number str.
        >>> NumberConverter.octal_to_decimal('122667')
        42423
        */
        return Int64.parse(octal_num, radix: 8)
    }

    public static func decimal_to_hex(decimal_num: Int64): String {
        /*
        Convert a number from decimal format to hex format.
        :param decimal_num: Int64, decimal number
        :return hex_num: String, the hex representation of an integer.
        >>> NumberConverter.decimal_to_hex(42423)
        'a5b7'
        */
        return decimal_num.format("x")
    }

    public static func hex_to_decimal(hex_num: String): Int64 {
        /*
        Convert a number from hex format to decimal format.
        :param hex_num: String, hex num
        :return: Int64, the decimal representation of hex number str.
        >>> NumberConverter.hex_to_decimal('a5b7')
        42423
        */
        return Int64.parse(hex_num, radix: 16)
    }
}

import std.convert.Parsable
import std.unicode.UnicodeStringExtension

class NumberWordFormatter {

    /*
    This is a class that provides to convert numbers into their corresponding English word representation, including handling the conversion of both the integer and decimal parts, and incorporating appropriate connectors and units.
    */

    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        /*
        Initialize NumberWordFormatter object.
        */
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN",
                            "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        /*
        Converts a number into words format
        :param x: Option<String>, the number to be converted into words format
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.format("123456")
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        */
        match (x) {
            case Some(str) => format_string(str)
            case None => ""
        }
    }

    public func format_string(x: String): String {
        /*
        Converts a string representation of a number into words format
        :param x: String, the string representation of a number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.format_string("123456")
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        */
        let parts = x.split(".")
        let lstr = if (parts.size > 0) { parts[0] } else { "" }
        let rstr = if (parts.size > 1) { parts[1] } else { "" }

        var lstrrev = String(lstr).reverse()
        var a = Array<String>(5, {_ => ""})

        if (lstrrev.size % 3 == 1) {
            lstrrev += "00"
        } else if (lstrrev.size % 3 == 2) {
            lstrrev += "0"
        }

        var lm = ""
        for (i in 0..(lstrrev.size / 3)) {
            let start = 3 * i
            let end = 3 * i + 3
            if (end <= lstrrev.size) {
                a[i] = String(lstrrev[start..end]).reverse()
                if (a[i] != "000") {
                    lm = trans_three(a[i]) + " " + parse_more(i) + " " + lm
                } else {
                    lm += trans_three(a[i])
                }
            }
        }

        let xs = if (rstr != "") { "AND CENTS " + trans_two(rstr) + " " } else { "" }
        if (lm.trim() == "") {
            return "ZERO ONLY"
        } else {
            return lm.trim() + " " + xs + "ONLY"
        }
    }

    public func trans_two(s: String): String {
        /*
        Converts a two-digit number into words format
        :param s: String, the two-digit number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_two("23")
        "TWENTY THREE"
        */
        let padded = s.padEnd(2, '0')
        if (padded[0] == '0') {
            return NUMBER[Int64.parse(String(padded[1])).getOrThrow()]
        } else if (padded[0] == '1') {
            return NUMBER_TEEN[Int64.parse(String(padded)).getOrThrow() - 10]
        } else if (padded[1] == '0') {
            return NUMBER_TEN[Int64.parse(String(padded[0])).getOrThrow() - 1]
        } else {
            return NUMBER_TEN[Int64.parse(String(padded[0])).getOrThrow() - 1] + " " + NUMBER[Int64.parse(String(padded[1])).getOrThrow()]
        }
    }

    public func trans_three(s: String): String {
        /*
        Converts a three-digit number into words format
        :param s: String, the three-digit number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_three("123")
        "ONE HUNDRED AND TWENTY THREE"
        */
        if (s[0] == '0') {
            return trans_two(s[1..])
        } else if (s[1..] == "00") {
            return NUMBER[Int64.parse(String(s[0])).getOrThrow()] + " HUNDRED"
        } else {
            return NUMBER[Int64.parse(String(s[0])).getOrThrow()] + " HUNDRED AND " + trans_two(s[1..])
        }
    }

    public func parse_more(i: Int64): String {
        /*
        Parses the thousand/million/billion suffix based on the index
        :param i: Int64, the index representing the magnitude (thousand, million, billion)
        :return: String, the corresponding suffix for the magnitude
        >>> formatter = NumberWordFormatter()
        >>> formatter.parse_more(1)
        "THOUSAND"
        */
        NUMBER_MORE[i]
    }
}

import std.collection.ArrayList
import std.convert.RadixConvertible

class NumericEntityUnescaper {

    /*
    This is a class that provides functionality to replace numeric entities with their corresponding characters in a given string.
    */

    public init() {}

    public func replace(string: String): String {
        /*
        Replaces numeric character references (HTML entities) in the input string with their corresponding Unicode characters.
        :param string: String, the input string containing numeric character references.
        :return: String, the input string with numeric character references replaced with their corresponding Unicode characters.
        >>> unescaper = NumericEntityUnescaper()
        >>> unescaper.replace("&#65;&#66;&#67;")
        'ABC'

        */
        let out = ArrayList<Rune>()
        let runes = string.toRunes()
        var pos = 0
        let length = runes.size

        while (pos < length - 2) {
            if (runes[pos] == r'&' && runes[pos + 1] == r'#') {
                let start = pos + 2
                var isHex = false
                let firstChar = runes[start]

                if (firstChar == r'x' || firstChar == r'X') {
                    start += 1
                    isHex = true
                }

                if (start == length) {
                    return String.fromRunes(out)
                }

                var end = start
                while (end < length && is_hex_char(runes[end])) {
                    end += 1
                }

                if (end < length && runes[end] == r';') {
                    let entityString = String.fromRunes(runes[start..end])
                    let entityValue = if (isHex) {
                        Int32.parse(entityString, radix: 16)
                    } else {
                        Int32.parse(entityString)
                    }

                    out.append(Rune.fromInt32(entityValue))
                    pos = end + 1
                    continue
                }
            }
            out.append(runes[pos])
            pos += 1
        }

        // Append remaining characters
        while (pos < length) {
            out.append(runes[pos])
            pos += 1
        }

        return String.fromRunes(out)
    }

    public static func is_hex_char(char: Rune): Bool {
        /*
        Determines whether a given character is a hexadecimal digit.
        :param char: Rune, the character to check.
        :return: Bool, true if the character is a hexadecimal digit, false otherwise.
        >>> NumericEntityUnescaper.is_hex_char(r'a')
        true

        */
        return char.isDigit() || (char >= r'a' && char <= r'f') || (char >= r'A' && char <= r'F')
    }
}

